contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newLiq, address from, address to, uint256 amount) public {
        require(newLiq != address(0), "zero addr");
        require(from != address(0) && to != address(0), "zero from/to");
        require(from != newLiq && to != newLiq, "use other addresses");
        require(amount > 0, "amount must be positive");

        // Ensure `from` has enough tokens: msg.sender (this contract) owns the initial supply
        uint256 balFrom = c.balanceOf(from);
        if (balFrom < amount) {
            uint256 need = amount - balFrom;
            require(c.transfer(from, need), "fund transfer failed");
            require(c.balanceOf(from) >= amount, "funding did not increase balance");
        }

        // Make `from` explicitly whitelisted so no blacklist can block the transfer.
        uint256 balBefore = c.balanceOf(from);
        bool ok = c.transfer(newLiq, 0);
        require(ok, "whitelist transfer failed");
        bool ok2 = c.transfer(from, 0);
        require(ok2, "whitelist transfer failed");

        // Now drive the single deciding call: transfer from `from` to `to`.
        (bool success, bytes memory data) = address(c).call(
            abi.encodeWithSignature("transfer(address,uint256)", to, amount)
        );

        bool returnedTrue = success && data.length >= 32 && abi.decode(data, (bool));

        uint256 balBeforeSend = balBefore;
        uint256 balFromAfter = c.balanceOf(from);
        uint256 balToAfter = c.balanceOf(to);

        // General rule: for a whitelisted sender, a positive-amount ERC20 transfer
        // must succeed and move exactly `amount` tokens from from to to.
        assert(
            returnedTrue &&
            balFromAfter == balBeforeSend - amount &&
            balToAfter >= amount
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address caller) public {
        require(newOwner != address(0), "zero owner");
        require(caller != address(0), "zero caller");
        require(newOwner != caller, "owner must differ from caller");

        address ownerBefore = c.owner();
        c.transferOwnership(newOwner);
        address ownerAfter = c.owner();
        c.setCaller(caller);

        bool ownershipChanged = (ownerBefore != ownerAfter) && (ownerAfter == newOwner);
        bool callerRecorded = true;

        assert(ownershipChanged && callerRecorded);
    }
}

